import * as T from 'three';
// Small relief and restrained reflections retain the authored textures and UVs.
export function industrialFinish176(root){const mats=new Map();root.traverse(o=>{if(!o.isMesh)return;const tune=m=>{if(!m?.isMeshStandardMaterial)return m;if(mats.has(m))return mats.get(m);const n=m.clone(),kind=m.userData.realism110,nm=m.name.toLowerCase();if(['mineral','floor'].includes(kind)||/concreto|hormigon|mortero|cemento/.test(nm)){n.normalScale?.multiplyScalar(.45);n.aoMapIntensity=Math.min(n.aoMapIntensity??.5,.15);n.roughness=.90;n.envMapIntensity=.35;}else if(['paint','panel'].includes(kind)){n.normalScale?.multiplyScalar(.6);n.roughness=.64;n.metalness=Math.min(n.metalness,.12);n.envMapIntensity=.65;if(n.clearcoat!==undefined)n.clearcoat=.08;}else if(['steel','brushed','polished'].includes(kind)){n.normalScale?.multiplyScalar(.65);n.roughness=Math.max(.28,n.roughness);n.envMapIntensity=.7;}n.userData={...n.userData,industrial176:true};mats.set(m,n);return n;};o.material=Array.isArray(o.material)?o.material.map(tune):tune(o.material);});return root;}
